  2	
  3	import hotel.messages.EmailSender;
  4	import hotel.messages.SentMessages;
  5	import hotel.notifications.FinanceNotifier;
  6	import hotel.notifications.GovernanceNotifier;
  7	import hotel.reports.OccupancyReport;
  8	import hotel.reports.RevenueReport;
  9	import hotel.reservations.PriceCalculator;
 10	import hotel.reservations.ReservationListener;
 11	import hotel.reservations.ReservationService;
 12	import hotel.reservations.ReservationStore;
 13	import hotel.rooms.Rooms;
 14	import hotel.web.HttpApi;
 15	import io.javalin.Javalin;
 16	import java.util.List;
 17	import javax.sql.DataSource;
 18	
 19	/** Puts the inn's pieces together and runs the HTTP server. */
 20	public final class Hotel {
 21	
 22	    private final Javalin server;
 23	
 24	    public Hotel(DataSource dataSource) {
 25	        Rooms rooms = new Rooms(dataSource);
 26	        ReservationStore store = new ReservationStore(dataSource);
 27	        SentMessages sentMessages = new SentMessages(dataSource);
 28	        EmailSender emailSender = new EmailSender(sentMessages);
 29	        // Who is told about reservation events: add or remove a listener here.
 30	        List<ReservationListener> listeners =
 31	                List.of(new GovernanceNotifier(emailSender), new FinanceNotifier(emailSender));
 32	        ReservationService reservations =
 33	                new ReservationService(rooms, store, new PriceCalculator(), emailSender, listeners);
 34	        HttpApi api = new HttpApi(
 35	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
 36	        this.server = api.server();
 37	    }
 38	
 39	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
 40	    public int start(int port) {
 41	        server.start(port);
 42	        return server.port();
 43	    }
 44	
 45	    public void stop() {
 46	        server.stop();
 47	    }
 48	
 49	    public static void main(String[] args) {
 50	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 51	        Database database = new Database(System.getenv());
 52	        new Hotel(database.dataSource()).start(port);
 53	    }
 54	}
